  function getTabs() {
    return tabs;
  }

  function renderSections(activeTab = 'tab-1') {
    return tabs.map(tab => {
      const isActive = activeTab === 'ALL' || activeTab === tab.id;
      return `
        <div class="anka-tab-section-wrapper" id="anka-sec-${tab.id}" style="display: ${isActive ? 'block' : 'none'};">
          <section class="page-section ${isActive ? 'active' : ''}" data-page="${tab.id}" data-section="${tab.sectionName}">
            ${tab.html}
          </section>
        </div>
      `;
    }).join('\n');
  }

  function setActiveTab(tabId) {
    tabs.forEach(tab => {
      const wrap = document.getElementById(`anka-sec-${tab.id}`);
      if (wrap) {
        const show = tabId === 'ALL' || tabId === tab.id;
        wrap.style.display = show ? 'block' : 'none';
        const sec = wrap.querySelector('.page-section');
        if (sec) {
          sec.classList.toggle('active', show);
        }
      }
    });

    document.querySelectorAll('.bf-tab-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.tabSec === tabId);
    });
  }

  function normalize(value) {
    return String(value || '')
      .replace(/\u00A0/g, ' ')
      .trim()
      .toLowerCase()
      .replace(/[\u00b0\u00ba]/g, '')
      .replace(/[_-]/g, ' ')
      .replace(/kias|kts|knots?|deg|degrees|km|kgs?|kg|psi|bar|ft|msl|v|volts?|amps?|c|percent|vs|%/g, ' ')
      .replace(/[,]/g, '.')
      .replace(/\./g, '')
      .replace(/[^0-9a-z+\-\s]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function exactAnswerMatch(answer, value) {
    const normAns = normalize(answer);
    const normVal = normalize(value);
    if (!normAns || !normVal) return false;
    return normAns === normVal;
  }

  function numericAnswerMatch(answer, value) {
    const answerDigits = String(answer || '').replace(/[^\d-]/g, '');
    const valueDigits = String(value || '').replace(/[^\d-]/g, '');
    return Boolean(answerDigits && valueDigits && answerDigits === valueDigits);
  }

  function isAnswerCorrect(acceptedAnswers, userValue) {
    if (!userValue || !String(userValue).trim()) return false;
    const cleanUser = String(userValue).trim();
    const list = Array.isArray(acceptedAnswers) ? acceptedAnswers : String(acceptedAnswers || '').split('|');
    
    // 1. Direct or numeric match across accepted options
    for (const ans of list) {
      const clean = String(ans || '').trim();
      if (!clean) continue;
      if (exactAnswerMatch(clean, cleanUser)) return true;
      if (numericAnswerMatch(clean, cleanUser)) return true;
    }

    // 2. Delegate to Grading engine if available for unit/synonym resolution
    const gradingEngine = (typeof Grading !== 'undefined' && Grading.evaluateAnswer)
      ? Grading
      : (typeof globalThis !== 'undefined' && globalThis.Grading ? globalThis.Grading : null);

    if (gradingEngine) {
      const primaryAns = list[0] || '';
      const evalRes = gradingEngine.evaluateAnswer(cleanUser, primaryAns, list);
      if (evalRes && evalRes.isCorrect) return true;
    }

    // 3. Fallback synonym checks (left/kiri, right/kanan)
    const uNorm = cleanUser.toLowerCase();
    for (const ans of list) {
      const aNorm = String(ans || '').toLowerCase().trim();
      if ((aNorm === 'left' || aNorm === 'kiri') && (uNorm === 'left' || uNorm === 'kiri')) return true;
      if ((aNorm === 'right' || aNorm === 'kanan') && (uNorm === 'right' || uNorm === 'kanan')) return true;
    }

    return false;
  }

  function isTableQuestion(qid) {
    if (!qid) return false;
    if (/^ANKA-LIM-0(0[6-9]|1[0-4])$/.test(qid)) return true; // Wind
    if (/^ANKA-LIM-0(19|[2-3][0-6])$/.test(qid)) return true; // Ku-Band
    if (/^ANKA-LIM-0(3[7-9]|[4-5][0-9]|6[0-2])$/.test(qid)) return true; // System
    if (/^ANKA-ACT-00[7-9]|ANKA-ACT-01[0-4]$/.test(qid)) return true; // Surface
    return false;
  }

  function getTableType(qid) {
    if (/^ANKA-LIM-0(0[6-9]|1[0-4])$/.test(qid)) return 'wind';
    if (/^ANKA-LIM-0(19|[2-3][0-6])$/.test(qid)) return 'kuband';
    if (/^ANKA-LIM-0(3[7-9]|[4-5][0-9]|6[0-2])$/.test(qid)) return 'system';
    if (/^ANKA-ACT-00[7-9]|ANKA-ACT-01[0-4]$/.test(qid)) return 'surface';
    return null;
  }

  function isDottedQuestion(qid) {
    if (!qid) return false;
    if (/^ANKA-LIM-00[1-5]$/.test(qid)) return true;
    if (/^ANKA-LIM-01[5-8]$/.test(qid)) return true;
    if (/^ANKA-ACT-00[1-6]|ANKA-ACT-015$/.test(qid)) return true;
    if (/^ANKA-RPMH-00[1-5]$/.test(qid)) return true;
    if (/^ANKA-RPML-00[1-6]$/.test(qid)) return true;
    if (/^ANKA-LDG-00[1-7]$/.test(qid)) return true;
    return false;
  }

  function renderTableCellInput(cell, activeQid, answersMap, isPractice, instantChecks) {
    if (!cell) return '<span class="cell-na">-</span>';
    const qid = cell.qid;
    const isActive = qid === activeQid;
    const userVal = (answersMap && answersMap[qid]) || '';
    const acceptedList = (cell.accepted || cell.answer || '').split('|').map(s => s.trim());
    const refAnswer = cell.answer || acceptedList[0] || '';
    
    let statusClass = '';
    let noteHtml = '';
    
    if (isPractice && userVal.trim()) {
      const isCorrect = isAnswerCorrect(acceptedList, userVal);
      if (isCorrect) {
        statusClass = 'is-valid';
      } else {
        statusClass = 'is-invalid';
        noteHtml = `<span class="cell-key-hint">(${refAnswer})</span>`;
      }
    }

    return `
      <div class="exam-table-cell-wrapper ${isActive ? 'is-active-cell' : ''} ${statusClass}">
        <input 
          type="text" 
          class="exam-cell-input ${statusClass}" 
          id="exam-cell-input-${qid}" 
          data-qid="${qid}" 
          value="${userVal.replace(/"/g, '&quot;')}" 
          placeholder="${isActive ? 'Jawaban aktif...' : '...'}" 
          autocomplete="off" 
          spellcheck="false" 
          oninput="App.onExamTableInput(event, '${qid}')" 
          onkeydown="App.onExamTableCellKeyDown(event, '${qid}')" 
        />
        ${isActive ? '<span class="active-cell-badge">▶ Soal Ini</span>' : ''}
        ${noteHtml}
      </div>
    `;
  }

